<template><view><view class="page-heading"><view><text class="kicker">MEMORIES</text><text class="title">一起吃过的饭</text><text class="copy">不是订单流水，是属于两个人的餐桌记忆。</text></view><button class="refresh" @click="$emit('refresh')">刷新</button></view>
  <view v-if="records.length" class="timeline"><view v-for="record in records" :key="record.id" class="record v2-card"><view class="timeline-dot"/><view class="record-date">{{ formatDate(record.completed_at) }}</view><text class="record-title">{{ record.title }}</text><view v-if="record.rating" class="rating"><text v-for="value in 5" :key="value" :class="{muted:value>record.rating}">★</text></view><text v-if="record.note" class="record-note">{{ record.note }}</text><view class="record-items"><text v-for="item in record.items" :key="item.id">{{ item.name }}</text></view><view v-if="record.images.length" class="record-images"><image v-for="(image,index) in record.images.slice(0,3)" :key="index" :src="image.url || image" mode="aspectFill"/></view></view></view>
  <EmptyState v-else title="第一顿饭还没完成" copy="完成一次共同菜单后，它会作为记忆出现在这里。" action="刷新记录" @action="$emit('refresh')" />
</view></template>
<script setup>import EmptyState from './EmptyState.vue';defineProps({records:{type:Array,default:()=>[]}});defineEmits(['refresh']);const formatDate=v=>v?new Date(v).toLocaleDateString('zh-CN',{month:'long',day:'numeric',year:'numeric'}):'最近'</script>
<style scoped>.page-heading{display:flex;justify-content:space-between;align-items:flex-start;margin:7px 3px 24px}.kicker{display:block;color:var(--color-primary);font-size:9px;letter-spacing:2px;font-weight:800}.title{display:block;font-family:Georgia,'Songti SC',serif;font-size:29px;font-weight:700;margin-top:7px}.copy{display:block;color:var(--color-muted);font-size:12px;margin-top:7px}.refresh{margin:0;background:transparent;color:var(--color-primary);font-size:12px;padding:7px}.refresh::after{border:0}.timeline{border-left:1px solid rgba(127,155,120,.3);padding-left:17px;margin-left:7px}.record{padding:18px;margin-bottom:14px;overflow:visible}.timeline-dot{position:absolute;width:9px;height:9px;border-radius:50%;background:var(--color-secondary);left:-23px;top:25px;border:3px solid var(--color-bg)}.record-date{font-size:10px;color:var(--color-primary);font-weight:700}.record-title{display:block;font-size:18px;font-weight:700;margin-top:5px}.rating{display:flex;gap:2px;margin-top:7px;color:var(--color-accent);font-size:13px}.rating .muted{color:rgba(127,119,110,.22)}.record-note{display:block;font-size:12px;color:var(--color-muted);line-height:1.6;margin-top:7px}.record-items{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.record-items text{padding:5px 9px;border-radius:15px;background:rgba(127,155,120,.1);font-size:10px;color:var(--color-secondary)}.record-images{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:13px}.record-images image{width:100%;height:90px;border-radius:10px}@media(min-width:720px){.timeline{display:grid;grid-template-columns:repeat(2,1fr);gap:15px;border:0;padding:0;margin:0}.timeline-dot{display:none}.record{margin:0}.record-images image{height:120px}}</style>
